{
  "name": "VisionMetric - IPD Scanner",
  "description": "A professional-grade web application to measure Interpupillary Distance (IPD) using AI vision. Capture a photo or upload an image to get precise measurements for VR headsets or eyewear.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface IPDResult {
  ipdMm: number;
  confidence: number;
  leftPupil: [number, number];
  rightPupil: [number, number];
  calibrationUsed: 'card' | 'average_iris' | 'estimation';
  explanation: string;
}

export type ScanStatus = 'idle' | 'capturing' | 'analyzing' | 'completed' | 'error';

import { GoogleGenAI, Type } from "@google/genai";
import { IPDResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function analyzeIPD(base64Image: string): Promise<IPDResult> {
  const model = ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          {
            text: `Analyze this face image to measure the Interpupillary Distance (IPD). 

            1. Identify the centers of the left and right pupils.
            2. If a standard ID/Credit card (85.6mm width) is visible held against the forehead or chin, use it as a reference scale.
            3. If no reference is found, use the standard human corneal diameter (average 11.7mm) as a fallback scale.
            4. Calculate the IPD in millimeters.

            Return the results in the specified JSON format.`
          },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image
            }
          }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER, description: "The measured IPD in millimeters" },
          confidence: { type: Type.NUMBER, description: "Confidence score between 0 and 1" },
          leftPupil: { 
            type: Type.ARRAY, 
            items: { type: Type.NUMBER }, 
            description: "[x, y] coordinates in pixel space (0-1000 relative)" 
          },
          rightPupil: { 
            type: Type.ARRAY, 
            items: { type: Type.NUMBER }, 
            description: "[x, y] coordinates in pixel space (0-1000 relative)" 
          },
          calibrationUsed: { 
            type: Type.STRING, 
            description: "Method used: 'card', 'average_iris', or 'estimation'" 
          },
          explanation: { type: Type.STRING, description: "Brief explanation of how the measurement was derived" }
        },
        required: ["ipdMm", "confidence", "leftPupil", "rightPupil", "calibrationUsed", "explanation"]
      }
    }
  });

  const response = await model;
  const result = JSON.parse(response.text || "{}");

  return {
    ipdMm: result.ipdMm,
    confidence: result.confidence,
    leftPupil: result.leftPupil as [number, number],
    rightPupil: result.rightPupil as [number, number],
    calibrationUsed: result.calibrationUsed as 'card' | 'average_iris' | 'estimation',
    explanation: result.explanation
  };
}

import React, { useState, useCallback, useRef } from 'react';
import { Camera, Upload, RefreshCw, Eye, Info, CheckCircle, AlertCircle, ChevronRight, HelpCircle } from 'lucide-react';
import { ScanStatus, IPDResult } from './types';
import { analyzeIPD } from './services/geminiService';

// Sub-components
const Header = () => (
  <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
    <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
      <div className="flex items-center gap-2">
        <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white">
          <Eye size={20} />
        </div>
        <span className="font-bold text-xl tracking-tight text-slate-800">VisionMetric</span>
      </div>
      <div className="flex items-center gap-4">
        <button className="text-slate-500 hover:text-slate-800 transition-colors">
          <HelpCircle size={20} />
        </button>
      </div>
    </div>
  </header>
);

const Footer = () => (
  <footer className="mt-12 py-8 px-4 border-t border-slate-200 text-center text-slate-500 text-sm">
    <p>© 2024 VisionMetric. AI-powered optical measurements.</p>
    <p className="mt-1">For informational purposes only. Consult an optometrist for medical prescriptions.</p>
  </footer>
);

export default function App() {
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [result, setResult] = useState<IPDResult | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const startCamera = async () => {
    try {
      setStatus('capturing');
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      setError("Camera access denied. Please check permissions.");
      setStatus('idle');
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
      tracks.forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
  };

  const captureFrame = async () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.8);
        setCapturedImage(dataUrl);
        stopCamera();
        processImage(dataUrl);
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        setCapturedImage(dataUrl);
        processImage(dataUrl);
      };
      reader.readAsDataURL(file);
    }
  };

  const processImage = async (dataUrl: string) => {
    try {
      setStatus('analyzing');
      const base64 = dataUrl.split(',')[1];
      const analysis = await analyzeIPD(base64);
      setResult(analysis);
      setStatus('completed');
    } catch (err) {
      console.error(err);
      setError("Failed to analyze image. Ensure your face is clearly visible.");
      setStatus('error');
    }
  };

  const reset = () => {
    setStatus('idle');
    setResult(null);
    setCapturedImage(null);
    setError(null);
    stopCamera();
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-grow max-w-4xl mx-auto w-full px-4 py-8">
        <div className="mb-8 text-center">
          <h1 className="text-3xl font-extrabold text-slate-900 mb-2">Measure Your IPD</h1>
          <p className="text-slate-600 max-w-md mx-auto">Get accurate interpupillary distance measurements for VR headsets, smart glasses, or prescription eyewear.</p>
        </div>

        {/* Action Buttons */}
        {status === 'idle' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-2xl mx-auto">
            <button 
              onClick={startCamera}
              className="flex flex-col items-center justify-center p-8 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl transition-all shadow-lg hover:shadow-indigo-200 group"
            >
              <Camera size={48} className="mb-4 group-hover:scale-110 transition-transform" />
              <span className="text-lg font-semibold">Start Face Scan</span>
              <span className="text-indigo-100 text-sm mt-1">Real-time camera measurement</span>
            </button>
            <div className="relative">
              <input 
                type="file" 
                accept="image/*" 
                onChange={handleFileUpload}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
              />
              <div className="flex flex-col items-center justify-center p-8 bg-white border-2 border-dashed border-slate-300 hover:border-indigo-400 text-slate-700 rounded-2xl transition-all group h-full">
                <Upload size={48} className="mb-4 text-slate-400 group-hover:text-indigo-500 transition-colors" />
                <span className="text-lg font-semibold">Upload Photo</span>
                <span className="text-slate-500 text-sm mt-1">Use an existing selfie</span>
              </div>
            </div>
          </div>
        )}

        {/* Camera View */}
        {status === 'capturing' && (
          <div className="max-w-2xl mx-auto">
            <div className="relative aspect-video bg-black rounded-3xl overflow-hidden shadow-2xl">
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                className="w-full h-full object-cover mirror"
              />
              {/* Overlays */}
              <div className="absolute inset-0 pointer-events-none border-[60px] border-black/40">
                <div className="w-full h-full border-2 border-dashed border-white/50 rounded-lg flex items-center justify-center">
                   <div className="w-48 h-64 border-2 border-indigo-400 rounded-[3rem] opacity-60"></div>
                </div>
              </div>
              <div className="absolute top-4 left-4 right-4 text-center">
                 <span className="bg-black/60 text-white px-3 py-1 rounded-full text-sm backdrop-blur-md">Position your face in the center</span>
              </div>
              <div className="absolute inset-x-0 top-0 h-1 bg-indigo-500 scanner-line opacity-50 shadow-[0_0_15px_rgba(99,102,241,0.8)]"></div>
            </div>
            <div className="mt-6 flex justify-center gap-4">
              <button 
                onClick={reset}
                className="px-6 py-3 bg-white text-slate-700 font-semibold rounded-xl border border-slate-200 hover:bg-slate-50"
              >
                Cancel
              </button>
              <button 
                onClick={captureFrame}
                className="px-8 py-3 bg-indigo-600 text-white font-semibold rounded-xl shadow-lg shadow-indigo-200 hover:bg-indigo-700"
              >
                Capture Measurement
              </button>
            </div>
          </div>
        )}

        {/* Analyzing View */}
        {status === 'analyzing' && (
          <div className="max-w-md mx-auto text-center py-20">
            <div className="relative inline-block mb-6">
              <RefreshCw size={64} className="text-indigo-600 animate-spin" />
              <Eye className="absolute inset-0 m-auto text-indigo-400" size={24} />
            </div>
            <h2 className="text-xl font-bold text-slate-800">Processing Your Image</h2>
            <p className="text-slate-500 mt-2">Our AI is detecting facial landmarks and calculating pupil distance...</p>
          </div>
        )}

        {/* Results View */}
        {status === 'completed' && result && (
          <div className="max-w-3xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Visual Confirmation */}
            <div className="relative aspect-square bg-slate-200 rounded-3xl overflow-hidden shadow-xl border-4 border-white">
              <img src={capturedImage!} alt="Scan" className="w-full h-full object-cover" />
              {/* Pupil markers */}
              <div 
                className="absolute w-4 h-4 -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full bg-indigo-500/80 shadow-[0_0_8px_rgba(255,255,255,0.8)]"
                style={{ left: `${result.leftPupil[0]/10}%`, top: `${result.leftPupil[1]/10}%` }}
              ></div>
              <div 
                className="absolute w-4 h-4 -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full bg-indigo-500/80 shadow-[0_0_8px_rgba(255,255,255,0.8)]"
                style={{ left: `${result.rightPupil[0]/10}%`, top: `${result.rightPupil[1]/10}%` }}
              ></div>
              {/* Dimension line */}
              <div 
                className="absolute h-0.5 bg-indigo-400 flex items-center justify-center"
                style={{
                  left: `${result.leftPupil[0]/10}%`,
                  top: `${result.leftPupil[1]/10}%`,
                  width: `${Math.abs(result.rightPupil[0] - result.leftPupil[0])/10}%`,
                }}
              >
                <div className="bg-white px-1.5 rounded-full text-[10px] font-bold text-indigo-600 shadow-sm border border-indigo-100">
                  {result.ipdMm}mm
                </div>
              </div>
            </div>

            {/* Data Panel */}
            <div className="flex flex-col gap-6">
              <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
                <div className="flex items-center gap-2 text-indigo-600 font-semibold mb-2">
                  <CheckCircle size={20} />
                  <span>Measurement Result</span>
                </div>
                <div className="flex items-baseline gap-2 mb-4">
                  <span className="text-6xl font-black text-slate-900 tracking-tight">{result.ipdMm}</span>
                  <span className="text-2xl font-bold text-slate-400">mm</span>
                </div>
                <div className="space-y-4">
                  <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl">
                    <span className="text-slate-500 text-sm">Confidence</span>
                    <span className="font-semibold text-slate-800">{(result.confidence * 100).toFixed(0)}%</span>
                  </div>
                  <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl">
                    <span className="text-slate-500 text-sm">Calibration Method</span>
                    <span className="font-semibold text-slate-800 capitalize">{result.calibrationUsed.replace('_', ' ')}</span>
                  </div>
                </div>
              </div>

              <div className="bg-indigo-50 border border-indigo-100 p-6 rounded-3xl">
                <div className="flex items-start gap-3">
                  <Info size={20} className="text-indigo-600 mt-1 shrink-0" />
                  <div>
                    <h3 className="font-bold text-indigo-900">Expert Note</h3>
                    <p className="text-indigo-800/80 text-sm mt-1 leading-relaxed">
                      {result.explanation}
                    </p>
                  </div>
                </div>
              </div>

              <button 
                onClick={reset}
                className="w-full py-4 bg-slate-900 text-white font-bold rounded-2xl hover:bg-slate-800 transition-colors shadow-lg flex items-center justify-center gap-2"
              >
                <RefreshCw size={20} />
                New Measurement
              </button>
            </div>
          </div>
        )}

        {/* Error State */}
        {status === 'error' && (
          <div className="max-w-md mx-auto bg-red-50 border border-red-100 p-8 rounded-3xl text-center">
            <AlertCircle size={48} className="text-red-500 mx-auto mb-4" />
            <h2 className="text-xl font-bold text-red-900">Analysis Failed</h2>
            <p className="text-red-700 mt-2 mb-6">{error || "Something went wrong."}</p>
            <button 
              onClick={reset}
              className="px-8 py-3 bg-red-600 text-white font-bold rounded-xl hover:bg-red-700 transition-colors"
            >
              Try Again
            </button>
          </div>
        )}

        {/* Instructions */}
        {status === 'idle' && (
          <div className="mt-20 max-w-2xl mx-auto">
            <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
              <ChevronRight className="text-indigo-600" />
              How to get the most accurate result
            </h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
                <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center font-bold mb-4">1</div>
                <h3 className="font-bold text-slate-800 mb-2">Good Lighting</h3>
                <p className="text-slate-500 text-sm">Face a bright window or use room lights. Avoid strong shadows on your eyes.</p>
              </div>
              <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
                <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center font-bold mb-4">2</div>
                <h3 className="font-bold text-slate-800 mb-2">Calibration Card</h3>
                <p className="text-slate-500 text-sm">Hold a standard ID/credit card against your forehead. Our AI uses this as a physical scale.</p>
              </div>
              <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
                <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center font-bold mb-4">3</div>
                <h3 className="font-bold text-slate-800 mb-2">Look Straight</h3>
                <p className="text-slate-500 text-sm">Keep your head level and look directly into the camera lens, not at the screen.</p>
              </div>
              <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
                <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center font-bold mb-4">4</div>
                <h3 className="font-bold text-slate-800 mb-2">Remove Glasses</h3>
                <p className="text-slate-500 text-sm">Glare from glasses can interfere with pupil detection. Take them off for the photo.</p>
              </div>
            </div>
          </div>
        )}
      </main>

      <Footer />
      <canvas ref={canvasRef} className="hidden" />
    </div>
