export interface IPDResult {
  ipdMm: number;
  confidence: number;
  leftPupil: [number, number];
  rightPupil: [number, number];
  pixelDistance: number;
  scalingFactor: number;
  calibrationUsed: 'card' | 'average_iris' | 'estimation';
  explanation: string;
}

export type ScanStatus = 'idle' | 'capturing' | 'analyzing' | 'completed' | 'error';

import { GoogleGenAI, Type } from "@google/genai";
import { IPDResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function analyzeIPD(base64Image: string): Promise<IPDResult> {
  const model = ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          {
            text: `Act as a specialized optical measurement AI. Your task is to calculate the Interpupillary Distance (IPD) from this image using strict geometric principles.

PROCEDURE:
1. DETECTION: Locate the centers of the left and right pupils precisely.
2. REFERENCE SCALING:
   - Search for a standard ID/Credit card (ISO/IEC 7810 ID-1 standard: 85.60 mm x 53.98 mm).
   - If found, calculate the scaling factor (mm per pixel) based on the card's dimensions in the image.
   - If no card is found, use the standard human corneal diameter (average 11.7mm based on clinical data common in Kaggle IPD datasets) as a biometric anchor to determine the scaling factor.
3. MATHEMATICAL CALCULATION:
   - Calculate the raw pixel distance (D_px) between pupils using the Euclidean distance formula: sqrt((x2-x1)^2 + (y2-y1)^2).
   - Apply the scaling factor (S) to the pixel distance: IPD_mm = D_px * S.
4. VALIDATION: Ensure the result is within the plausible human range (typically 50mm to 75mm, median ~63mm).

Return the results in the specified JSON format.`
          },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image
            }
          }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER, description: "The final measured IPD in millimeters" },
          pixelDistance: { type: Type.NUMBER, description: "The Euclidean distance between pupils in pixels" },
          scalingFactor: { type: Type.NUMBER, description: "The calculated mm per pixel ratio" },
          confidence: { type: Type.NUMBER, description: "Confidence score (0-1)" },
          leftPupil: { 
            type: Type.ARRAY, 
            items: { type: Type.NUMBER }, 
            description: "[x, y] coordinates in pixel space" 
          },
          rightPupil: { 
            type: Type.ARRAY, 
            items: { type: Type.NUMBER }, 
            description: "[x, y] coordinates in pixel space" 
          },
          calibrationUsed: { 
            type: Type.STRING, 
            description: "Method: 'card', 'average_iris', or 'estimation'" 
          },
          explanation: { type: Type.STRING, description: "Detailed derivation mentioning Euclidean distance and the scaling factor source." }
        },
        required: ["ipdMm", "pixelDistance", "scalingFactor", "confidence", "leftPupil", "rightPupil", "calibrationUsed", "explanation"]
      }
    }
  });

  const response = await model;
  const result = JSON.parse(response.text || "{}");

  return {
    ipdMm: result.ipdMm,
    pixelDistance: result.pixelDistance,
    scalingFactor: result.scalingFactor,
    confidence: result.confidence,
    leftPupil: result.leftPupil as [number, number],
    rightPupil: result.rightPupil as [number, number],
    calibrationUsed: result.calibrationUsed as 'card' | 'average_iris' | 'estimation',
    explanation: result.explanation
  };
}

