export interface IPDResult {
  ipdMm: number;
  confidence: number;
  rightOuterLimbus: [number, number];
  leftInnerLimbus: [number, number];
  pixelDistance: number;
  scalingFactor: number;
  calibrationUsed: 'card' | 'average_iris' | 'estimation';
  explanation: string;
}

export type ScanStatus = 'idle' | 'capturing' | 'analyzing' | 'completed' | 'error';

import { GoogleGenAI, Type } from "@google/genai";
import { IPDResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function analyzeIPD(base64Image: string): Promise<IPDResult> {
  const model = ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [
      {
        parts: [
          {
            text: `Act as a specialized clinical optical measurement AI. Your task is to calculate the Interpupillary Distance (IPD) using a specific anatomical measurement technique.

MEASUREMENT RULE:
- You must measure the distance from the OUTER LIMBUS of the subject's RIGHT EYE to the INNER LIMBUS of the subject's LEFT EYE.
- The limbus is the border between the iris and the white sclera.
- Outer Limbus (Right Eye): The edge of the iris furthest from the nose on the subject's right eye.
- Inner Limbus (Left Eye): The edge of the iris closest to the nose on the subject's left eye.

PROCEDURE:
1. DETECTION: Locate the coordinates for the Right Outer Limbus and Left Inner Limbus precisely.
2. REFERENCE SCALING:
   - Identify a standard ID/Credit card (85.60 mm width) if present for scaling.
   - Fallback: Use standard corneal diameter (11.7mm) from clinical datasets to derive the scaling factor (mm/pixel).
3. MATHEMATICAL CALCULATION:
   - Use the Euclidean distance formula: sqrt((x2-x1)^2 + (y2-y1)^2) to find the pixel distance (D_px) between these two specific limbus points.
   - Apply the scaling factor (S) to the pixel distance: IPD_mm = D_px * S.
4. VALIDATION: Cross-reference with Kaggle IPD dataset statistical norms (50mm-75mm).

Return the results in the specified JSON format.`
          },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image
            }
          }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER, description: "The final measured IPD in millimeters" },
          pixelDistance: { type: Type.NUMBER, description: "Euclidean distance between Right Outer Limbus and Left Inner Limbus in pixels" },
          scalingFactor: { type: Type.NUMBER, description: "The calculated mm per pixel ratio" },
          confidence: { type: Type.NUMBER, description: "Confidence score (0-1)" },
          rightOuterLimbus: { 
            type: Type.ARRAY, 
            items: { type: Type.NUMBER }, 
            description: "[x, y] coordinates of the subject's right eye outer limbus" 
          },
          leftInnerLimbus: { 
            type: Type.ARRAY, 
            items: { type: Type.NUMBER }, 
            description: "[x, y] coordinates of the subject's left eye inner limbus" 
          },
          calibrationUsed: { 
            type: Type.STRING, 
            description: "Method: 'card', 'average_iris', or 'estimation'" 
          },
          explanation: { type: Type.STRING, description: "Brief derivation text mentioning the specific limbus points and Euclidean math used." }
        },
        required: ["ipdMm", "pixelDistance", "scalingFactor", "confidence", "rightOuterLimbus", "leftInnerLimbus", "calibrationUsed", "explanation"]
      }
    }
  });

  const response = await model;
  const result = JSON.parse(response.text || "{}");

  return {
    ipdMm: result.ipdMm,
    pixelDistance: result.pixelDistance,
    scalingFactor: result.scalingFactor,
    confidence: result.confidence,
    rightOuterLimbus: result.rightOuterLimbus as [number, number],
    leftInnerLimbus: result.leftInnerLimbus as [number, number],
    calibrationUsed: result.calibrationUsed as 'card' | 'average_iris' | 'estimation',
    explanation: result.explanation
  };
}

